// DANGEROUS: Ambiguity/Dangling Else
// else binds to NEAREST unmatched if (inner_cond)
if (outer_cond)
    if (inner_cond)
        stmt1;
    else
        stmt2; // If outer=T, inner=F

// BEST PRACTICE: Use Braces {} to enforce grouping

if (outer_cond) {
    if (inner_cond)
        stmt3;
    // Optional: else for inner_cond goes here
} else {
    // This else clearly belongs to if (outer_cond)
    stmt4; // If outer=F
}
